import{_ as p,a0 as o,w as d,s as h,ao as l,I as n,x as i,a1 as t,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Cron 任务入门指南 | LCTT x X-CMD","titleTemplate":false,"description":"Cron 任务入门指南 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Cron 任务入门指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Cron 任务入门指南 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180504 A Beginners Guide To Cron Jobs","title":"Cron 任务入门指南","tag":"201805","desc":""},"relativePath":"201805/20180504 A Beginners Guide To Cron Jobs.md","filePath":"[post].md"}'),g={name:"201805/20180504 A Beginners Guide To Cron Jobs.md"};function r(c,s,k,b,u,f){const e=o("Link");return d(),h("div",null,[s[18]||(s[18]=l(`<h1 id="cron-任务入门指南" tabindex="-1">Cron 任务入门指南 <a class="header-anchor" href="#cron-任务入门指南" aria-label="Permalink to “Cron 任务入门指南”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/05/cron-jobs1-720x340.jpg" alt=""></p><p><strong>Cron</strong> 是您可以在任何类 Unix 操作系统中找到的最有用的实用程序之一。它用于安排命令在特定时间执行。这些预定的命令或任务被称为 “Cron 任务”。Cron 通常用于运行计划备份、监视磁盘空间、定期删除不再需要的文件（例如日志文件）、运行系统维护任务等等。在本简要指南中，我们将看到 Linux 中 Cron 任务的基本用法。</p><h3 id="cron-任务入门指南-1" tabindex="-1">Cron 任务入门指南 <a class="header-anchor" href="#cron-任务入门指南-1" aria-label="Permalink to “Cron 任务入门指南”">​</a></h3><p>cron 任务的典型格式是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>分钟(0-59) 小时(0-24) 日(1-31) 月(1-12) 星期(0-6) 要执行的命令</span></span></code></pre></div><p>只需记住 cron 任务的格式或打印下面的插图并将其放在你桌面上即可。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/cron-job-format-1.png" alt=""></p><p>在上图中，星号表示特定的时间块。</p><p>要显示当前登录用户的 crontab 文件的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ crontab -l</span></span></code></pre></div><p>要编辑当前用户的 cron 任务，请执行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ crontab -e</span></span></code></pre></div><p>如果这是第一次编辑此文件，会询问你使用哪个编辑器来编辑此文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>no crontab for sk - using an empty one</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Select an editor. To change later, run &#39;select-editor&#39;.</span></span>
<span class="line"><span>1. /bin/nano &lt;---- easiest</span></span>
<span class="line"><span>2. /usr/bin/vim.basic</span></span>
<span class="line"><span>3. /usr/bin/vim.tiny</span></span>
<span class="line"><span>4. /bin/ed</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Choose 1-4 [1]:</span></span></code></pre></div><p>选择适合你的编辑器。这里是一个示例 crontab 文件的样子。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/cron-jobs-1.png" alt=""></p><p>在这个文件中，你需要添加你的 cron 任务。</p><p>要编辑其他用户的 crontab，例如 ostechnix，请执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ crontab -u ostechnix -e</span></span></code></pre></div><p>让我们看看一些例子。</p><p>要 <strong>每分钟</strong> 执行一次 cron 任务，需使用如下格式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>* * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>要每 5 分钟运行一次 cron 任务，请在 crontab 文件中添加以下内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*/5 * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>要在每 1/4 个小时（每 15 分钟）运行一次 cron 任务，请添加以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*/15 * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>要每小时的第 30 分钟运行一次 cron 任务，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>30 * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>您还可以使用逗号定义多个时间间隔。例如，以下 cron 任务每小时运行三次，分别在第 0、 5 和 10 分钟运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0,5,10 * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每半小时运行一次 cron 任务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*/30 * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每小时运行一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每 2 小时运行一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 */2 * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每天运行一项（在 00:00 运行）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每天凌晨 3 点运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 3 * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每周日运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 * * SUN &lt;command-to-execute&gt;</span></span></code></pre></div><p>或使用，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 * * 0 &lt;command-to-execute&gt;</span></span></code></pre></div><p>它将在每周日的午夜 00:00 运行。</p><p>星期一至星期五每天运行一次，亦即每个工作日运行一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 * * 1-5 &lt;command-to-execute&gt;</span></span></code></pre></div><p>这项工作将于 00:00 开始。</p><p>每个月运行一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 1 * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>于每月第 1 天的 16:15 运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>15 16 1 * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每季度运行一次，亦即每隔 3 个月的第 1 天运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 1 */3 * &lt;command-to-execute&gt;</span></span></code></pre></div><p>在特定月份的特定时间运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>5 0 * 4 * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每个四月的 00:05 运行。</p><p>每 6 个月运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 1 */6 * &lt;command-to-execute&gt;</span></span></code></pre></div><p>这个定时任务将在每六个月的第一天的 00:00 运行。</p><p>每年运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 1 1 * &lt;command-to-execute&gt;</span></span></code></pre></div><p>这项 cron 任务将于 1 月份的第一天的 00:00 运行。</p><p>我们也可以使用以下字符串来定义任务。</p><p><code>@reboot</code> 在每次启动时运行一次。 <code>@yearly</code> 每年运行一次。 <code>@annually</code>（和 <code>@yearly</code> 一样）。 <code>@monthly</code> 每月运行一次。 <code>@weekly</code> 每周运行一次。 <code>@daily</code> 每天运行一次。 <code>@midnight</code> （和 <code>@daily</code> 一样）。 <code>@hourly</code> 每小时运行一次。</p><p>例如，要在每次重新启动服务器时运行任务，请将此行添加到您的 crontab 文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@reboot &lt;command-to-execute&gt;</span></span></code></pre></div><p>要删除当前用户的所有 cron 任务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ crontab -r</span></span></code></pre></div>`,70)),n("p",null,[s[1]||(s[1]=i("还有一个名为 [crontab.guru] ",-1)),t(e,{href:"https://crontab.guru/"},{default:a(()=>[...s[0]||(s[0]=[i("4",-1)])]),_:1}),s[2]||(s[2]=i(" 的专业网站，用于学习 cron 任务示例。这个网站提供了很多 cron 任务的例子。",-1))]),s[19]||(s[19]=l('<p>有关更多详细信息，请查看手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man crontab</span></span></code></pre></div><p>那么，就是这样。到此为止，您应该对 cron 任务以及如何在世使用它们有了一个基本的了解。后续还会介绍更多的优秀工具。敬请关注！！</p><p>干杯!</p><hr>',5)),n("p",null,[s[4]||(s[4]=i("via: ",-1)),t(e,{href:"https://www.ostechnix.com/a-beginners-guide-to-cron-jobs/"},{default:a(()=>[...s[3]||(s[3]=[i("https://www.ostechnix.com/a-beginners-guide-to-cron-jobs/",-1)])]),_:1})]),n("p",null,[s[9]||(s[9]=i("作者：",-1)),t(e,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[5]||(s[5]=[i("SK",-1)])]),_:1}),s[10]||(s[10]=i(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[6]||(s[6]=[i("lujun9972",-1)])]),_:1}),s[11]||(s[11]=i(" 译者：",-1)),t(e,{href:"https://github.com/KevinSJ"},{default:a(()=>[...s[7]||(s[7]=[i("KevinSJ",-1)])]),_:1}),s[12]||(s[12]=i(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[8]||(s[8]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[13]||(s[13]=[i("LCTT",-1)])]),_:1}),s[16]||(s[16]=i(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...s[14]||(s[14]=[i("Linux中国",-1)])]),_:1}),s[17]||(s[17]=i(" 荣誉推出",-1))])])}const x=p(g,[["render",r]]);export{C as __pageData,x as default};
